def link_existing_registrations(apps, schema_editor):
    """One Student per person (matched on phone number); every earlier registration is linked to theirs."""
    import secrets
    Student = apps.get_model('courses', 'Student')
    Reg = apps.get_model('courses', 'CourseRegistration')
    letters = 'ABCDEFGHJKLMNPQRSTUVWXYZ'
    used, by_key = set(), {}
    for reg in Reg.objects.order_by('registered_at'):
        # one Student per registration, as in service.link_student: unverified phone numbers never merge people
        key = str(reg.pk)
        st = by_key.get(key)
        if st is None:
            while True:
                code = f'{secrets.randbelow(9000) + 1000}-' + ''.join(secrets.choice(letters) for _ in range(3))
                if code not in used:
                    used.add(code)
                    break
            st = by_key[key] = Student.objects.create(name=reg.name, phone=reg.phone, phone_key=reg.phone_key, email=reg.email,
                                                      student_code=code)
        Reg.objects.filter(pk=reg.pk).update(student=st)


